/* Retourne true si toutes les cases du rectangle (x, y, w, h) sont constructibles (TILE_FREE). */
static inline bool standard_farm_can_build(int x, int y, int w, int h) {
    if (x < 0 || y < 0 || x + w > FARM_WIDTH || y + h > FARM_HEIGHT) {
        return false;
    }
    for (int dy = 0; dy < h; dy++) {
        for (int dx = 0; dx < w; dx++) {
            if (STANDARD_FARM_GRID[y + dy][x + dx] != TILE_FREE) {
                return false;
            }
        }
    }
    return true;
}

